const items = $input.all();

const output = [];

for (const item of items) {

  const data = item.json;

  const content = data.pageContent || "";
  const competitor = data.competitor || "Konga";
  const website = data.website || "https://www.konga.com";

  // Extract products
  const products = [];

  const productRegex = /([^[]+)\[\/product\/([^\]]+)\]/g;

  let match;

  while ((match = productRegex.exec(content)) !== null) {

    const name = match[1].trim();
    const slug = match[2];

    const position = match.index;
    const context = content.substring(
      Math.max(0, position - 400),
      position
    );

    const prices = context.match(/₦[\d,]+/g) || [];

    products.push({
      id: slug,
      name: name,
      url: `${website}/product/${slug}`,
      price: prices.length
        ? Number(prices[prices.length - 1].replace(/[₦,]/g, ""))
        : null
    });
  }

  // Extract promotions
  const promotions = [
    ...new Set(
      content.match(
        /\d+%\s*Off|Flash Sales Reloaded|Buy More\. Save More|Limited Stock|Crazy Value Zone|Konga Yakata/gi
      ) || []
    )
  ];

  // Retrieve previous history
  const previousData = data.previous_data || {};

  const oldProducts = previousData.products || [];
  const oldPromotions = previousData.promotions || [];

  // Compare products
  const oldMap = new Map(
    oldProducts.map(p => [p.id, p])
  );

  const newProducts = [];
  const priceIncreases = [];
  const priceDecreases = [];

  for (const product of products) {

    const old = oldMap.get(product.id);

    if (!old) {
      newProducts.push(product);
      continue;
    }

    if (
      old.price !== null &&
      product.price !== null &&
      old.price !== product.price
    ) {

      if (product.price > old.price) {
        priceIncreases.push({
          product: product.name,
          old_price: old.price,
          new_price: product.price
        });
      } else {
        priceDecreases.push({
          product: product.name,
          old_price: old.price,
          new_price: product.price
        });
      }
    }
  }

  // Find removed products
  const currentIds = new Set(products.map(p => p.id));

  const removedProducts = oldProducts.filter(
    p => !currentIds.has(p.id)
  );

  // Compare promotions
  const newPromotions = promotions.filter(
    p => !oldPromotions.includes(p)
  );

  const removedPromotions = oldPromotions.filter(
    p => !promotions.includes(p)
  );

  // Detect changes
  const changesDetected =
    newProducts.length > 0 ||
    removedProducts.length > 0 ||
    priceIncreases.length > 0 ||
    priceDecreases.length > 0 ||
    newPromotions.length > 0 ||
    removedPromotions.length > 0;

  output.push({
    json: {
      competitor,
      website,
      checked_at: new Date().toISOString(),

      changes_detected: changesDetected,
      competitor_id: data.competitor_id || "1",

      change_summary: {
        new_products: newProducts,
        removed_products: removedProducts,
        price_increases: priceIncreases,
        price_decreases: priceDecreases,
        new_promotions: newPromotions,
        removed_promotions: removedPromotions
      },

      current_data: {
        products,
        promotions
      },

      previous_data: previousData,

      total_products: products.length
    }
  });
}

return output;
